-- Issue #307 (Kindle party membership and human primaries): party membership (one party per citizen) and the primary election, voter receipt and anonymous ranked-ballot tables, separate from the civic_* presidential tables. The ballot table carries no timestamp and no citizen. Additive tables only.
CREATE TABLE IF NOT EXISTS party_members ( clerk_user_id TEXT PRIMARY KEY REFERENCES citizens(clerk_user_id), party_id TEXT NOT NULL CHECK(party_id IN ('steady-hand','open-ledger','dockside-builders')), joined_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS primary_elections ( id TEXT PRIMARY KEY, nation_id TEXT NOT NULL CHECK(nation_id='kindle'), policy TEXT NOT NULL CHECK(policy IN ('tier1-human-v1','preview-citizen-v1')), opens_at INTEGER NOT NULL, closes_at INTEGER NOT NULL, closed_at INTEGER, result_json TEXT, CHECK(closes_at=opens_at+259200), CHECK(closed_at IS NULL OR closed_at>=closes_at), CHECK(result_json IS NULL OR closed_at IS NOT NULL) );
CREATE TABLE IF NOT EXISTS primary_voter_receipts ( election_id TEXT NOT NULL REFERENCES primary_elections(id), clerk_user_id TEXT NOT NULL REFERENCES citizens(clerk_user_id), party_id TEXT NOT NULL CHECK(party_id IN ('steady-hand','open-ledger','dockside-builders')), request_id TEXT NOT NULL UNIQUE, checked_at INTEGER NOT NULL, ballot_written INTEGER NOT NULL DEFAULT 0 CHECK(ballot_written IN (0,1)), policy TEXT NOT NULL CHECK(policy IN ('tier1-human-v1','preview-citizen-v1')), PRIMARY KEY(election_id,clerk_user_id) );
CREATE TABLE IF NOT EXISTS primary_anonymous_ballots ( id TEXT PRIMARY KEY, election_id TEXT NOT NULL REFERENCES primary_elections(id), party_id TEXT NOT NULL CHECK(party_id IN ('steady-hand','open-ledger','dockside-builders')), ranking TEXT NOT NULL, policy TEXT NOT NULL CHECK(policy IN ('tier1-human-v1','preview-citizen-v1')) );
CREATE INDEX IF NOT EXISTS idx_primary_ballots_election ON primary_anonymous_ballots(election_id);
